Index: src/pages/games/age-of-war.astro
===================================================================
--- src/pages/games/age-of-war.astro	
+++ src/pages/games/age-of-war.astro	
@@ -0,0 +1,43 @@
+---
+const Game = "Age of War";
+import Layout from "../../layout/layout.astro";
+---
+<html lang="en">
+  <head>
+    <meta charset="UTF-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+    <meta name="description" content="Play Age of War superfun online. - superfun and ready to play!" />
+    <title>{Game}</title>
+    <script defer src="/_vercel/insights/script.js"></script>
+  </head>
+  <Layout Game={Game}>
+    <div style="text-align: center">
+      <div id="container" style="border: #ccc 0px solid; height: 100%; width: 100%"></div>
+      <script src="/ruffle/ruffle.js" is:inline></script>
+      <script data-astro-rerun is:inline>
+        window.RufflePlayer = window.RufflePlayer || {};
+        (function() {
+          var container = document.getElementById("container");
+          if (!container) return;
+          var ruffle = window.RufflePlayer.newest();
+          if (!ruffle) return;
+          container.innerHTML = '';
+          var player = ruffle.createPlayer();
+          container.appendChild(player);
+          player.style.height = "96vh";
+          player.style.width = "98vw";
+          player.load("/flash/ageofwar.swf");
+        })();
+      </script>
+    </div>
+    <script type="text/javascript">
+      atOptions = {
+        key: "1cc5f63f55fc28b4c469b5e4e2f1a79d",
+        format: "iframe",
+        height: 250,
+        width: 300,
+        params: {},
+      };
+    </script>
+  </Layout>
+</html>

